const MAX_DELAY_MS = 30_000;

// Delay before replay attempt n (1-based): base doubled per attempt, capped.
export function backoffMs(attempt: number, baseMs: number): number {
  return Math.min(baseMs * 2 ** (attempt - 1), MAX_DELAY_MS);
}
