    expect(res.status).toBe(202);
    const body = await res.json();
    expect(body).toMatchObject({ id: 'evt_000001', tenant: 'tenant-a', type: 'invoice.paid', attempts: 0 });
  });

  it('rejects a request without the X-Tenant header', async () => {
    const { send } = setup();
    const res = await send('/webhooks', { method: 'POST', body: JSON.stringify({ type: 'x' }) });
    expect(res.status).toBe(400);
  });

  it('rejects an unknown tenant', async () => {
    const { postWebhook } = setup();
    expect((await postWebhook('nobody', { type: 'x' })).status).toBe(404);
  });

  it('rejects a body that is not JSON', async () => {
    const { send } = setup();
    const res = await send('/webhooks', { method: 'POST', tenant: 'tenant-a', body: 'not json' });
    expect(res.status).toBe(400);
  });

  it('rejects an event without a type', async () => {
    const { postWebhook } = setup();
    expect((await postWebhook('tenant-a', { data: 1 })).status).toBe(400);
  });

