export interface Tenant {
  id: string;
  name: string;
  createdAt: string;
}

const TENANT_ID = /^[a-z0-9]+(-[a-z0-9]+)*$/;

export class TenantError extends Error {
  constructor(
    message: string,
    readonly code: 'invalid' | 'exists',
  ) {
    super(message);
  }
}

export class TenantRegistry {
  private tenants = new Map<string, Tenant>();

  constructor(seed: Array<Pick<Tenant, 'id' | 'name'>> = []) {
    for (const t of seed) this.create(t.id, t.name);
  }

  list(): Tenant[] {
    return [...this.tenants.values()];
  }

  get(id: string): Tenant | undefined {
    return this.tenants.get(id);
  }

  create(id: string, name: string, now = new Date()): Tenant {
    if (!TENANT_ID.test(id)) throw new TenantError('id must be lowercase letters, digits and dashes', 'invalid');
    if (name.trim() === '') throw new TenantError('name is required', 'invalid');
    if (this.tenants.has(id)) throw new TenantError(`tenant ${id} exists`, 'exists');
    const tenant = { id, name: name.trim(), createdAt: now.toISOString() };
    this.tenants.set(id, tenant);
    return tenant;
  }
}
